script:
frappe.ui.form.on('Sales Invoice', {
    refresh(frm) {
        if (frm.doc.currency === "USD") {
			frm.set_value("debit_to", "110.320 - Account.Receivable (USD) - CP");
		} else {
			frm.set_value("debit_to", "110.310 - Account.Receivable (IDR) - CP");
		}
        setTimeout(() => {
            frm.page.remove_inner_button('Delivery Note', 'Create');
            frm.page.remove_inner_button('Dunning', 'Create');
            frm.page.remove_inner_button('Maintenance Schedule', 'Create');
            frm.page.remove_inner_button('Invoice Discounting', 'Create');

            $("[data-label='Timesheet']").hide();
            $("[data-label='Delivery%20Note']").hide();

        }, 500);
    },
	onload(frm) {
        setTimeout(() => {
            $("[data-doctype='Dunning']").hide();
            $("[data-doctype='Timesheet']").hide();
            $("[data-doctype='Delivery Note']").hide();
            $("[data-doctype='POS Invoice']").hide();
            $("[data-doctype='Auto Repeat']").hide();
            $("[data-doctype='Purchase Invoice']").hide();



            $('.form-dashboard-section .row > div.col-md-4').each(function() {
                let $kolom = $(this);

                // Cek apakah ada satupun link yang MASIH TERLIHAT di dalam kolom ini
                // Kita cek atribut style display secara langsung
                let adaLinkTerlihat = $kolom.find('.document-link').filter(function() {
                    return $(this).css('display') !== 'none';
                }).length > 0;

                // Jika TIDAK ADA link yang terlihat (semuanya hidden), sembunyikan kolomnya
                if (!adaLinkTerlihat) {
                    $kolom.hide();
                }
            });

        }, 100);
	}
})

frappe.ui.form.on('Sales Order', {
    onload(frm) {
        setTimeout(() => {
            $("[data-doctype='Pick List']").hide();
            $("[data-doctype='Delivery Note']").hide();
            $("[data-doctype='Maintenance Visit']").hide();
            $("[data-doctype='Purchase Order']").hide();
            $("[data-doctype='Project']").hide();
            $("[data-doctype='Work Order']").hide();
            $("[data-doctype='BOM']").hide();
            $("[data-doctype='Blanket Order']").hide();
            $("[data-doctype='Auto Repeat']").hide();
            $("[data-doctype='Stock Reservation Entry']").hide();
            $("[data-doctype='Material Request']").hide();
            $("[data-doctype='Quotation']").hide();

            $('.form-dashboard-section .row > div.col-md-4').each(function() {
                let $kolom = $(this);

                // Cek apakah ada satupun link yang MASIH TERLIHAT di dalam kolom ini
                // Kita cek atribut style display secara langsung
                let adaLinkTerlihat = $kolom.find('.document-link').filter(function() {
                    return $(this).css('display') !== 'none';
                }).length > 0;

                // Jika TIDAK ADA link yang terlihat (semuanya hidden), sembunyikan kolomnya
                if (!adaLinkTerlihat) {
                    $kolom.hide();
                }
            });

        }, 100);
    },
	validate(frm) {
        // Pastikan custom_sales terisi
        if (frm.doc.custom_sales) {
            // Jika sales_team kosong, tambahkan baris baru
            if (!frm.doc.sales_team || frm.doc.sales_team.length === 0) {
                let row = frm.add_child('sales_team');
                row.sales_person = frm.doc.custom_sales;
                row.allocated_percentage = 100; // Opsional: set default allocation
            } else {
                // Update baris pertama dengan nilai custom_sales
                frm.doc.sales_team[0].sales_person = frm.doc.custom_sales;
            }
            // Refresh field sales_team agar perubahan terlihat di UI
            frm.refresh_field('sales_team');
        }
    },
    custom_kurs(frm) {
        if (frm.doc.custom_kurs && frm.doc.custom_kurs > 0) {
            frm.set_value('conversion_rate', frm.doc.custom_kurs);
        }
    },
    currency(frm) {
        if (frm.doc.custom_kurs && frm.doc.custom_kurs > 0) {
            // Tunggu sebentar agar ERPNext selesai set conversion_rate dari API
            setTimeout(() => {
                frm.set_value('conversion_rate', frm.doc.custom_kurs);
            }, 500);
        }
    },
});

frappe.ui.form.on('Purchase Order', {
    refresh: function(frm) {
        setTimeout(function() {
            $('div.inner-group-button[data-label="Get%20Items%20From"]').hide();
            $('div.inner-group-button[data-label="Tools"]').hide();
            hide_create_menu_by_role(frm);
        }, 300);
    }
});

function hide_create_menu_by_role(frm) {

    // Sembunyikan menu berdasarkan role
    if (!frappe.user.has_role('Accounts User')) {
        $('div.inner-group-button[data-label="Create"]').hide();
        $('a.dropdown-item[data-label="Payment"]').hide();
        $('a.dropdown-item[data-label="Payment%20Request"]').hide();

        $('a.dropdown-item[data-label="Vendor%20Receipt"]').hide();
        $('a.dropdown-item[data-label="Vendor%20Invoice"]').hide();
    } else {
        $('a.dropdown-item[data-label="Vendor%20Receipt"]').hide();
    }
}

frappe.ui.form.on('Purchase Invoice', {
	refresh: function(frm) {
        setTimeout(function() {

            hide_create_menu_by_role(frm);
        }, 300);
    }
})


function hide_create_menu_by_role(frm) {

    // Sembunyikan menu berdasarkan role
    if (frappe.user.has_role('Accounts User')) {

        $('a.dropdown-item[data-label="Vendor%20Receipt"]').hide();

    } 
}
